import { expect, expectStatus, test } from "../../fixtures";

test("A certificate expiry date that cannot be parsed gets a null value with low confidence", { tag: "@DOC-03" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const vendor = await factory.vendor();
  const document = await factory.upload(vendor.id, "insurance_certificate", "insurance_certificate_unparseable.txt");

  // Act: extraction runs in the background, so wait for the document to leave "processing".
  await expect
    .poll(
      async () => {
        const current = await expectStatus<{ status: string }>(await member.get(`/api/documents/${document.id}`), 200);
        return current.status;
      },
      { message: "processing finishes for the insurance certificate", timeout: 30_000 },
    )
    .toBe("extracted");
  const extraction = await expectStatus<{
    fields: Record<string, { value: string | null; confidence: number }>;
  }>(await member.get(`/api/documents/${document.id}/extraction`), 200);

  // Assert
  const expiry = extraction.fields.expiry_date;
  expect(expiry, "extraction includes an expiry_date field").toBeDefined();
  expect(expiry.value, "unparseable expiry date is null").toBeNull();
  expect(expiry.confidence, "confidence for the unparseable expiry date").toBeLessThan(0.5);
});
